import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {validateDeck} from '../science-bulk/quiz-battle-core.mjs';
const root=new URL('./release/',import.meta.url);
const prior=JSON.parse(fs.readFileSync(new URL('./prior-questions.json',import.meta.url)));
const file=name=>new URL(name,root);
const has=name=>fs.existsSync(file(name));
function harness(){
 const loaded=[];let context;
 const window={AssessmentQuestionBank:structuredClone(prior),AssessmentBuilderSubjects:[{id:'science',label:'Science',years:Object.fromEntries([7,8,9,10].map(y=>[y,{legacy:true}]))}],addEventListener(){}};
 function run(name){loaded.push(name);if(has(name))vm.runInContext(fs.readFileSync(file(name),'utf8'),context,{filename:name});else if(name==='assessment-marking-key-normalizer.js')vm.runInContext(fs.readFileSync(new URL('./assessment-marking-key-normalizer.js',import.meta.url),'utf8'),context);}
 const document={createElement(){return{}},getElementById(){return null},head:{appendChild(s){run(s.src.split('?')[0]);s.onload?.()}},write(s){for(const m of s.matchAll(/src="([^"]+)"/g))run(m[1].split('?')[0]);}};
 context=vm.createContext({window,document,console,setTimeout(){}});
 return{window,loaded,run,context};
}
const browser=harness();browser.run('assessment-question-bank.js');assert.equal(browser.window.AssessmentQuestionBank.length,1978);
const builder=harness();builder.run('assessment-builder-bank-loader.js');const y8=await builder.window.AssessmentBankLoader.load('science',8);assert(y8.length>100);assert.equal(builder.window.AssessmentQuestionBank.length,1978);assert(y8.some(q=>q.importBatch==='repo-science-batch16'));assert(y8.every(q=>q.keyRows?.length));
const practice=harness();practice.run('student-quiz-bank-loader.js');const questions=await practice.window.StudentQuizBankLoader.load();assert.equal(questions.length,1978);assert(questions.some(q=>q.importBatch==='repo-science-batch16'&&q.marks===0.5));
const w=practice.window;
for(let n=12;n<=46;n++)if(has(`scsa-source-pack-repo-science-batch${n}.js`))vm.runInContext(fs.readFileSync(file(`scsa-source-pack-repo-science-batch${n}.js`),'utf8'),practice.context);
let gameCount=0,figureRefs=0;
for(let n=12;n<=46;n++){
 if(!has(`science-source-assessment-games-batch${n}.json`))continue;
 const packs=JSON.parse(fs.readFileSync(file(`science-source-assessment-games-batch${n}.json`)));
 for(const set of Object.values(packs.sets)){validateDeck(set.questions);assert.equal(set.count,set.questions.length);gameCount+=set.count;for(const q of set.questions)assert(w.AssessmentQuestionBank.some(x=>x.id===q.sourceQuestionId&&x.battleSetId===set.id&&!x.sourceReviewRequired));}
}
for(const q of w.AssessmentQuestionBank.filter(q=>Number(q.importBatch.slice(-2))>=12)){
 assert.equal(q.keyRows.reduce((n,r)=>n+r.marks,0),q.marks,q.id);
 if(q.sourceReviewRequired){assert.equal(q.correctIndex,undefined);assert.equal(q.battleSetId,undefined);assert.equal(q.markingMode,'manual');}
 for(const html of [q.question,q.diagram,q.keyDiagram||''])for(const m of html.matchAll(/data-scsa-image="([^"]+)"/g)){assert(w.ScsaSourceImagePacks[q.importBatch][m[1]],q.id);figureRefs++;}
}
const status=JSON.parse(fs.readFileSync(file('science-assessment-import-status.json')));
assert.equal(status.importedQuestions,w.AssessmentQuestionBank.length);assert.equal(status.activeAdditionalQuestionRequest.addedQuestions,1015);assert.equal(status.activeAdditionalQuestionRequest.remainingQuestions,0);
const idx=JSON.parse(fs.readFileSync(file('lesson-game-index.json')));for(let n=12;n<=46;n++)if(has(`science-source-assessment-games-batch${n}.json`))for(const meta of Object.values(JSON.parse(fs.readFileSync(file(`science-source-assessment-games-batch${n}.json`))).sets)){assert(idx.sets.some(x=>x.id===meta.id&&x.count===meta.count));}

for(const suffix of ['23b','23c','23d'])assert(questions.some(q=>q.id==='SCI-REPO-Y9-SBY-2017-EXT-'+suffix),'distinct source equation restored: '+suffix);
assert(questions.some(q=>q.id==='SCI-REPO-Y10-ARAN-2015-S1CHEM-4b'),'distinct shaded region diagram restored');
const allIds=new Set(questions.map(q=>q.id));for(const batch of status.batches)for(const alias of batch.duplicateQuestionAliases||[])assert(allIds.has(alias.existingQuestionId),'alias target exists: '+alias.existingQuestionId);

const oldGames=JSON.parse(fs.readFileSync(file('science-source-assessment-games-batch03.json')));
for(const game of Object.values(oldGames.sets))validateDeck(game.questions);
for(const suffix of ['02','03']){const id='SCI-REPO-Y10-NAR-2024-UNIVERSE-MC'+suffix;const q=questions.find(q=>q.id===id);assert(q.sourceReviewRequired);assert.equal(q.correctIndex,undefined);assert.equal(q.battleSetId,undefined);assert(!Object.values(oldGames.sets).some(g=>g.questions.some(q=>(q.sourceQuestionId||q.id)===id)));}
assert.equal(idx.sets.find(q=>q.id==='science-source-y10-narrogin-2024-universe').count,12);
assert(questions.find(q=>q.id==='SCI-REPO-Y8-SBY-2018-MICROSCOPES-MC04').stem.includes('µm'));
assert.equal(status.battleEligibleQuestions,questions.filter(q=>q.sourceAssessment&&q.battleSetId).length,'source battle counter matches actual eligible records');
assert.equal(status.multipleChoice,questions.filter(q=>q.type==='Multiple choice').length,'MC counter matches loaded bank');
console.log(JSON.stringify({result:'PASS',browserQuestions:1978,builderYear8:y8.length,practiceQuestions:questions.length,earlier1000RequestAdded:1015,addedThisRequest:status.allAssessmentsRequest.addedQuestions,newGameQuestions:gameCount,figureReferences:figureRefs,coverage:Object.fromEntries([7,8,9,10].map(y=>[y,questions.filter(q=>q.year===y).length])),checks:['browser bank loader','assessment builder loader and marking normalizer','practice loader and fractional marks','game index and real battle validator','source figure references','mark totals and manual-review exclusions','source import counter']},null,2));
